    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES — DATA MERIDIAN THEME
           Dark navy + teal/cyan + amber, technical data aesthetic
           =========================================== */
        :root {
            --bg-primary:    #07111d;
            --bg-secondary:  #0d1b2d;
            --bg-card:       #112236;
            --bg-card-2:     #162a42;
            --accent-teal:   #00c9a7;
            --accent-blue:   #4facfe;
            --accent-amber:  #f5a623;
            --accent-red:    #ff5c5c;
            --text-primary:  #daeeff;
            --text-secondary:#7aa0bc;
            --text-muted:    #3d6278;
            --border:        rgba(79, 172, 254, 0.14);
            --border-teal:   rgba(0, 201, 167, 0.22);

            --font-display: 'Syne', sans-serif;
            --font-body:    'DM Sans', sans-serif;
            --font-mono:    'DM Mono', monospace;

            /* Typography — all clamp() */
            --title-size:    clamp(1.5rem, 5vw, 4rem);
            --h2-size:       clamp(1.2rem, 3vw, 2.2rem);
            --h3-size:       clamp(1rem, 2.5vw, 1.6rem);
            --body-size:     clamp(0.75rem, 1.4vw, 1.05rem);
            --small-size:    clamp(0.62rem, 0.95vw, 0.82rem);
            --mono-size:     clamp(0.6rem, 1vw, 0.8rem);

            /* Spacing */
            --slide-padding: clamp(1.25rem, 4vw, 3.5rem);
            --content-gap:   clamp(0.5rem, 2vh, 1.5rem);
            --element-gap:   clamp(0.3rem, 1vh, 0.8rem);

            /* Easing */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --dur: 0.6s;
        }

        /* ===========================================
           BASE RESET
           =========================================== */
        *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

        /* ===========================================
           VIEWPORT-BASE.CSS — MANDATORY (pasted in full)
           =========================================== */
        html, body { height: 100%; overflow-x: hidden; }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        /* Each slide = exact viewport height */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        /* Content container */
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }

        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }

        .feature-list, .bullet-list { gap: clamp(0.4rem, 1vh, 1rem); }
        .feature-list li, .bullet-list li { font-size: var(--body-size); line-height: 1.4; }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }

        /* Short viewports */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap:   clamp(0.35rem, 1.2vw, 0.9rem);
                --title-size:    clamp(1.2rem, 4.5vw, 2.5rem);
                --h2-size:       clamp(1rem, 2.8vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap:   clamp(0.25rem, 1vw, 0.6rem);
                --title-size:    clamp(1rem, 4vw, 1.8rem);
                --body-size:     clamp(0.65rem, 1.1vw, 0.9rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size:    clamp(0.95rem, 3.5vw, 1.4rem);
                --h2-size:       clamp(0.85rem, 2.5vw, 1.2rem);
                --body-size:     clamp(0.6rem, 1vw, 0.8rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.2rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }
        /* ===========================================
           END VIEWPORT-BASE.CSS
           =========================================== */

        /* ===========================================
           GLOBAL THEME STYLES
           =========================================== */
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
        }

        /* Subtle grid background for data slides */
        .bg-grid::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(79, 172, 254, 0.035) 1px, transparent 1px),
                linear-gradient(90deg, rgba(79, 172, 254, 0.035) 1px, transparent 1px);
            background-size: clamp(35px, 5vw, 55px) clamp(35px, 5vw, 55px);
            pointer-events: none;
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0; left: 0;
            height: 2px;
            background: linear-gradient(90deg, var(--accent-teal), var(--accent-blue));
            box-shadow: 0 0 8px rgba(0, 201, 167, 0.5);
            transition: width 0.3s ease;
            z-index: 1000;
            width: 0%;
        }

        /* ===========================================
           NAV DOTS (right side)
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.6rem, 1.5vw, 1.25rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: clamp(5px, 1vh, 9px);
            z-index: 1000;
        }
        .nav-dot {
            width: clamp(5px, 0.7vw, 7px);
            height: clamp(5px, 0.7vw, 7px);
            border-radius: 50%;
            background: var(--text-muted);
            cursor: pointer;
            transition: all 0.3s ease;
        }
        .nav-dot.active {
            background: var(--accent-teal);
            box-shadow: 0 0 6px var(--accent-teal);
            transform: scale(1.4);
        }
        .nav-dot:hover { background: var(--accent-blue); }

        /* ===========================================
           SLIDE NUMBER
           =========================================== */
        .slide-num {
            position: absolute;
            bottom: clamp(0.6rem, 1.5vh, 1.2rem);
            right: clamp(0.8rem, 2vw, 2rem);
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--text-muted);
            letter-spacing: 0.08em;
            z-index: 10;
        }

        /* ===========================================
           SOURCE FOOTNOTE
           =========================================== */
        .source-note {
            position: absolute;
            bottom: clamp(0.6rem, 1.5vh, 1.2rem);
            left: var(--slide-padding);
            font-family: var(--font-mono);
            font-size: clamp(0.52rem, 0.75vw, 0.65rem);
            color: var(--text-muted);
            z-index: 10;
        }

        /* ===========================================
           REVEAL ANIMATIONS — triggered by .visible class
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(18px);
            transition: opacity var(--dur) var(--ease-out-expo),
                        transform var(--dur) var(--ease-out-expo);
        }
        .slide.visible .reveal { opacity: 1; transform: translateY(0); }

        .reveal-left {
            opacity: 0;
            transform: translateX(-28px);
            transition: opacity var(--dur) var(--ease-out-expo),
                        transform var(--dur) var(--ease-out-expo);
        }
        .slide.visible .reveal-left { opacity: 1; transform: translateX(0); }

        .reveal-right {
            opacity: 0;
            transform: translateX(28px);
            transition: opacity var(--dur) var(--ease-out-expo),
                        transform var(--dur) var(--ease-out-expo);
        }
        .slide.visible .reveal-right { opacity: 1; transform: translateX(0); }

        .reveal-scale {
            opacity: 0;
            transform: scale(0.92);
            transition: opacity 0.65s var(--ease-out-expo),
                        transform 0.65s var(--ease-out-expo);
        }
        .slide.visible .reveal-scale { opacity: 1; transform: scale(1); }

        /* Stagger delays */
        .d1 { transition-delay: 0.05s; }
        .d2 { transition-delay: 0.15s; }
        .d3 { transition-delay: 0.25s; }
        .d4 { transition-delay: 0.35s; }
        .d5 { transition-delay: 0.45s; }
        .d6 { transition-delay: 0.55s; }
        .d7 { transition-delay: 0.65s; }

        /* ===========================================
           SHARED COMPONENT: SLIDE HEADER
           =========================================== */
        .slide-tag {
            display: inline-flex;
            align-items: center;
            gap: 0.4em;
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-teal);
            letter-spacing: 0.16em;
            text-transform: uppercase;
            background: rgba(0, 201, 167, 0.07);
            border: 1px solid rgba(0, 201, 167, 0.2);
            padding: 0.22em 0.65em;
            border-radius: 3px;
            margin-bottom: clamp(0.4rem, 1.2vh, 0.9rem);
        }

        .slide-heading {
            font-family: var(--font-display);
            font-size: var(--h2-size);
            font-weight: 700;
            color: var(--text-primary);
            line-height: 1.15;
            margin-bottom: clamp(0.5rem, 1.8vh, 1.2rem);
        }
        .slide-heading em {
            font-style: normal;
            color: var(--accent-teal);
        }

        /* ===========================================
           CHART COMPONENTS
           =========================================== */
        .chart-wrap {
            flex: 1;
            min-height: 0;
            display: flex;
            flex-direction: column;
        }
        .chart-wrap svg {
            width: 100%;
            flex: 1;
            min-height: 0;
            max-height: min(46vh, 340px);
            overflow: visible;
        }

        .chart-legend {
            display: flex;
            gap: clamp(0.75rem, 2vw, 1.5rem);
            flex-wrap: wrap;
            margin-top: clamp(0.25rem, 0.8vh, 0.6rem);
        }
        .legend-item {
            display: flex;
            align-items: center;
            gap: 0.45em;
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--text-secondary);
        }
        .legend-swatch {
            width: 18px;
            height: 3px;
            border-radius: 2px;
            flex-shrink: 0;
        }

        /* ===========================================
           SLIDE 1: TITLE
           =========================================== */
        #s1 {
            justify-content: center;
            background:
                radial-gradient(ellipse at 85% 15%, rgba(79,172,254,0.07) 0%, transparent 55%),
                radial-gradient(ellipse at 15% 85%, rgba(0,201,167,0.07) 0%, transparent 55%),
                var(--bg-primary);
        }
        #s1 .grid-decor {
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(79,172,254,0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(79,172,254,0.03) 1px, transparent 1px);
            background-size: 56px 56px;
            pointer-events: none;
        }
        #s1 .accent-line {
            position: absolute;
            left: 0; top: 0; bottom: 0;
            width: 3px;
            background: linear-gradient(180deg, transparent 0%, var(--accent-teal) 30%, var(--accent-blue) 70%, transparent 100%);
            opacity: 0.6;
        }

        .title-inner {
            position: relative;
            z-index: 1;
            padding: var(--slide-padding);
            max-width: min(92vw, 960px);
        }

        .title-eyebrow {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-teal);
            letter-spacing: 0.22em;
            text-transform: uppercase;
            margin-bottom: clamp(0.6rem, 2vh, 1.25rem);
            display: flex;
            align-items: center;
            gap: 0.6em;
        }
        .title-eyebrow::before {
            content: '';
            display: block;
            width: 2em;
            height: 1px;
            background: var(--accent-teal);
        }

        .title-main {
            font-family: var(--font-display);
            font-size: clamp(1.9rem, 5.5vw, 4.2rem);
            font-weight: 800;
            line-height: 1.08;
            color: var(--text-primary);
            margin-bottom: clamp(0.5rem, 1.5vh, 1rem);
        }
        .title-main .t-highlight {
            color: var(--accent-teal);
        }

        .title-sub {
            font-size: clamp(0.82rem, 1.7vw, 1.15rem);
            color: var(--text-secondary);
            line-height: 1.55;
            margin-bottom: clamp(1rem, 3.5vh, 2.2rem);
            max-width: 70ch;
        }

        .title-meta-row {
            display: flex;
            gap: clamp(1.5rem, 4vw, 3rem);
            flex-wrap: wrap;
            align-items: center;
        }
        .meta-block { display: flex; flex-direction: column; gap: 0.2em; }
        .meta-lbl {
            font-family: var(--font-mono);
            font-size: clamp(0.55rem, 0.8vw, 0.68rem);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.14em;
        }
        .meta-val {
            font-family: var(--font-mono);
            font-size: clamp(0.68rem, 1vw, 0.85rem);
            color: var(--text-secondary);
        }
        .meta-sep {
            width: 1px;
            height: 32px;
            background: var(--border);
        }

        /* ===========================================
           CONTENT SLIDE BASE
           =========================================== */
        .content-slide {
            padding: var(--slide-padding);
            display: flex;
            flex-direction: column;
        }

        /* ===========================================
           SLIDE 4: REQUESTS & CONNECTIONS — split layout
           =========================================== */
        .split-layout {
            display: grid;
            grid-template-columns: 1fr 2fr;
            gap: clamp(1rem, 3vw, 2rem);
            flex: 1;
            min-height: 0;
            align-items: start;
        }
        @media (max-width: 680px) {
            .split-layout { grid-template-columns: 1fr; }
        }

        .stat-stack {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 0.9rem);
        }
        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.65rem, 1.8vw, 1.25rem);
        }
        .stat-num {
            font-family: var(--font-mono);
            font-size: clamp(1.6rem, 4vw, 3rem);
            font-weight: 500;
            color: var(--accent-blue);
            line-height: 1;
        }
        .stat-lbl {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.3em;
            line-height: 1.3;
        }
        .stat-delta {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-amber);
            margin-top: 0.4em;
        }
        .stat-decline {
            color: var(--accent-teal);
        }

        .chart-col {
            display: flex;
            flex-direction: column;
            min-height: 0;
        }
        .chart-col-label {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--text-muted);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: 0.4em;
        }

        /* ===========================================
           SLIDE 5: HTTPS — large stat + chart
           =========================================== */
        .https-layout {
            display: grid;
            grid-template-columns: 1fr 1.6fr;
            gap: clamp(1.5rem, 4vw, 3rem);
            align-items: center;
            flex: 1;
            min-height: 0;
        }
        @media (max-width: 680px) {
            .https-layout { grid-template-columns: 1fr; }
        }

        .mega-stat {
            font-family: var(--font-mono);
            font-size: clamp(3.5rem, 11vw, 7.5rem);
            font-weight: 500;
            color: var(--accent-teal);
            line-height: 1;
            text-shadow: 0 0 50px rgba(0,201,167,0.25);
            letter-spacing: -0.02em;
        }
        .mega-unit {
            font-size: clamp(1.5rem, 4vw, 3rem);
            color: var(--accent-teal);
            opacity: 0.7;
        }
        .mega-label {
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: 0.5em;
            line-height: 1.4;
        }
        .https-badges {
            display: flex;
            gap: 0.6em;
            flex-wrap: wrap;
            margin-top: clamp(0.5rem, 1.5vh, 1rem);
        }
        .badge {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            background: rgba(0,201,167,0.08);
            border: 1px solid rgba(0,201,167,0.2);
            color: var(--accent-teal);
            padding: 0.25em 0.7em;
            border-radius: 3px;
        }

        /* ===========================================
           SLIDE 6: PROTOCOL ADOPTION
           =========================================== */
        .protocol-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.75rem, 2vw, 1.5rem);
            flex: 1;
            min-height: 0;
        }
        @media (max-width: 600px) {
            .protocol-layout { grid-template-columns: 1fr; }
        }

        .proto-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1.4rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.35rem, 1vh, 0.65rem);
        }
        .proto-card.h3-card {
            border-color: rgba(245,166,35,0.28);
            background: rgba(245,166,35,0.04);
        }
        .proto-name {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            letter-spacing: 0.14em;
            text-transform: uppercase;
            color: var(--text-muted);
        }
        .proto-pct {
            font-family: var(--font-mono);
            font-size: clamp(2rem, 5vw, 3.8rem);
            font-weight: 500;
            color: var(--accent-blue);
            line-height: 1;
        }
        .proto-card.h3-card .proto-pct { color: var(--accent-amber); }
        .proto-detail {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }
        .proto-bar-track {
            height: 3px;
            background: var(--bg-card-2);
            border-radius: 2px;
            overflow: hidden;
            margin-top: 0.2em;
        }
        .proto-bar-fill {
            height: 100%;
            border-radius: 2px;
            background: var(--accent-blue);
            width: 0%;
            transition: width 1s var(--ease-out-expo) 0.4s;
        }
        .proto-card.h3-card .proto-bar-fill { background: var(--accent-amber); }
        .slide.visible .proto-bar-fill { width: var(--fill-w); }

        .proto-mini-chart {
            display: flex;
            flex-direction: column;
            gap: 0.3em;
        }
        .proto-mini-label {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
        }

        .caveat-box {
            background: rgba(79,172,254,0.05);
            border: 1px solid rgba(79,172,254,0.15);
            border-radius: 6px;
            padding: clamp(0.4rem, 1.2vw, 0.75rem);
            margin-top: clamp(0.3rem, 1vh, 0.6rem);
        }
        .caveat-text {
            font-size: var(--small-size);
            color: var(--text-muted);
            font-style: italic;
            line-height: 1.45;
        }

        /* ===========================================
           SLIDE 7: FONT-DISPLAY
           =========================================== */
        .font-layout {
            display: grid;
            grid-template-columns: 1fr 1.6fr;
            gap: clamp(1.5rem, 3vw, 2.5rem);
            flex: 1;
            min-height: 0;
            align-items: start;
        }
        @media (max-width: 680px) {
            .font-layout { grid-template-columns: 1fr; }
        }

        .font-stat-col {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vh, 0.9rem);
        }
        .font-stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.65rem, 1.8vw, 1.2rem);
        }
        .font-stat-val {
            font-family: var(--font-mono);
            font-size: clamp(1.8rem, 4vw, 3rem);
            font-weight: 500;
            line-height: 1;
        }
        .font-stat-val.desktop { color: var(--accent-blue); }
        .font-stat-val.mobile  { color: var(--accent-teal); }
        .font-stat-lbl {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.3em;
        }
        .font-stat-delta {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-amber);
            margin-top: 0.3em;
        }
        .foit-box {
            background: rgba(245,166,35,0.06);
            border: 1px solid rgba(245,166,35,0.18);
            border-radius: 8px;
            padding: clamp(0.5rem, 1.5vw, 1rem);
        }
        .foit-tag {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-amber);
            letter-spacing: 0.1em;
            margin-bottom: 0.35em;
        }
        .foit-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        /* ===========================================
           SLIDE 8: KEY TAKEAWAYS
           =========================================== */
        .takeaway-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.45rem, 1.2vw, 0.85rem);
            flex: 1;
            min-height: 0;
            align-content: start;
        }
        @media (max-width: 600px) {
            .takeaway-grid { grid-template-columns: 1fr; }
        }

        .tak-card {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: clamp(0.65rem, 1.5vw, 1.1rem);
            display: flex;
            flex-direction: column;
            gap: 0.3em;
        }
        .tak-num {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-teal);
            letter-spacing: 0.1em;
        }
        .tak-title {
            font-family: var(--font-display);
            font-size: clamp(0.82rem, 1.4vw, 1.05rem);
            font-weight: 700;
            color: var(--text-primary);
            line-height: 1.25;
        }
        .tak-body {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.45;
        }

        .cta-banner {
            grid-column: 1 / -1;
            background: linear-gradient(135deg, rgba(0,201,167,0.08), rgba(79,172,254,0.08));
            border: 1px solid rgba(0,201,167,0.28);
            border-radius: 8px;
            padding: clamp(0.65rem, 1.5vw, 1.1rem);
            display: flex;
            align-items: center;
            gap: clamp(0.75rem, 2vw, 1.25rem);
        }
        .cta-icon {
            font-size: clamp(1rem, 2.5vw, 1.6rem);
            flex-shrink: 0;
        }
        .cta-text-wrap { flex: 1; }
        .cta-lbl {
            font-family: var(--font-mono);
            font-size: var(--mono-size);
            color: var(--accent-teal);
            letter-spacing: 0.12em;
            text-transform: uppercase;
            margin-bottom: 0.2em;
        }
        .cta-body {
            font-size: var(--small-size);
            color: var(--text-primary);
            line-height: 1.4;
        }
    </style>
</head>
<body>

    <!-- Progress bar — width updated by JS -->
    <div class="progress-bar" id="progressBar"></div>

    <!-- Nav dots — generated by JS -->
    <nav class="nav-dots" id="navDots" aria-label="Slide navigation"></nav>

    <!-- ============================================================
         SLIDE 1 — TITLE
         ============================================================ -->
    <section class="slide" id="s1" aria-label="Title slide">
        <div class="grid-decor"></div>
        <div class="accent-line"></div>

        <div class="title-inner">
            <div class="title-eyebrow reveal d1">HTTP Archive · State of the Web</div>

            <h1 class="title-main reveal d2">
                State of the Web<br>
                <span class="t-highlight">2020 – 2025</span>
            </h1>

            <p class="title-sub reveal d3">
                Tracking Page Weight, Protocols &amp; Security at Scale —<br>
                HTTP Archive Trends in Transfer Size, Request Efficiency, HTTPS Adoption, and CSS Best Practices
            </p>

            <div class="title-meta-row reveal d4">
                <div class="meta-block">
                    <span class="meta-lbl">Data Source</span>
                    <span class="meta-val">HTTP Archive</span>
                </div>
                <div class="meta-sep"></div>
                <div class="meta-block">
                    <span class="meta-lbl">Time Range</span>
                    <span class="meta-val">Jan 2020 – Mar 2026</span>
                </div>
                <div class="meta-sep"></div>
                <div class="meta-block">
                    <span class="meta-lbl">Coverage</span>
                    <span class="meta-val">Desktop &amp; Mobile</span>
                </div>
                <div class="meta-sep"></div>
                <div class="meta-block">
                    <span class="meta-lbl">Audience</span>
                    <span class="meta-val">Web Perf Engineers · Front-End Architects</span>
                </div>
            </div>
        </div>

        <div class="slide-num">01 / 08</div>
    </section>

    <!-- ============================================================
         SLIDE 2 — CRAWL SAMPLE SIZE
         ============================================================ -->
    <section class="slide bg-grid content-slide" id="s2" aria-label="Crawl sample size growth">

        <div class="slide-tag reveal d1">01 — Sample Size</div>
        <h2 class="slide-heading reveal d2">
            Crawl Sample Size <em>Tripled:</em><br>~5M → 16M Desktop URLs Since 2020
        </h2>

        <!-- Dual-line time-series SVG chart -->
        <div class="chart-wrap reveal d3">
            <svg viewBox="0 0 580 210" preserveAspectRatio="none" aria-label="Sample size time series chart">
                <!-- Grid lines -->
                <g stroke="rgba(79,172,254,0.08)" stroke-width="1">
                    <line x1="50" y1="20" x2="545" y2="20"/>
                    <line x1="50" y1="62" x2="545" y2="62"/>
                    <line x1="50" y1="104" x2="545" y2="104"/>
                    <line x1="50" y1="146" x2="545" y2="146"/>
                    <line x1="50" y1="188" x2="545" y2="188"/>
                </g>
                <!-- Y-axis labels -->
                <g font-family="DM Mono, monospace" font-size="9" fill="rgba(79,172,254,0.45)" text-anchor="end">
                    <text x="44" y="23">18M</text>
                    <text x="44" y="65">13M</text>
                    <text x="44" y="107">8M</text>
                    <text x="44" y="149">3M</text>
                </g>
                <!-- X-axis labels -->
                <g font-family="DM Mono, monospace" font-size="9" fill="rgba(79,172,254,0.45)" text-anchor="middle">
                    <text x="50"  y="203">2020</text>
                    <text x="149" y="203">2021</text>
                    <text x="248" y="203">2022</text>
                    <text x="347" y="203">2023</text>
                    <text x="446" y="203">2024</text>
                    <text x="545" y="203">2025</text>
                </g>

                <!-- Y-axis line -->
                <line x1="50" y1="20" x2="50" y2="188" stroke="rgba(79,172,254,0.2)" stroke-width="1"/>

                <!--
                    Scale: Y-axis 0–18M over 168px (y=20 top, y=188 bottom)
                    1M = 9.33px; y = 188 - (val * 9.33)
                    X-axis: 5 years = 495px (x=50 to x=545), 99px/year

                    Desktop:  5M stable Jan2020–Jun2022, sharp jump ~Sep2022 to 15M,
                              plateau to 16M by mid-2023, stable to 2025
                    Mobile:   3.5M stable Jan2020–Jun2022, jump to 10M ~Sep2022,
                              grows to 12.5M by mid-2023, stable to 2025
                -->

                <!-- IQR / band areas (subtle fill) -->
                <!-- Desktop band (slightly lighter shade) -->
                <polygon
                    points="50,141 248,141 297,47 346,42 495,37 545,37 545,37 495,37 446,37 347,42 297,47 248,141 149,141 50,141"
                    fill="rgba(79,172,254,0.04)"
                    stroke="none"
                />
                <!-- Mobile band -->
                <polygon
                    points="50,155 248,155 297,94 346,90 495,71 545,71 545,71 495,71 347,90 297,94 248,155 149,155 50,155"
                    fill="rgba(0,201,167,0.04)"
                    stroke="none"
                />

                <!-- Desktop line: 5M → 5M (Jan2020–Jun2022) → jump to 15M (Sep2022) → 16M steady -->
                <!-- y for 5M  = 188 - 5*9.33  = 141.4 ≈ 141 -->
                <!-- y for 15M = 188 - 15*9.33 = 47.95 ≈ 48 -->
                <!-- y for 16M = 188 - 16*9.33 = 37.7  ≈ 38 -->
                <polyline
                    points="50,141 149,141 248,141 297,48 346,42 446,38 545,38"
                    fill="none"
                    stroke="#4facfe"
                    stroke-width="2.5"
                    stroke-linejoin="round"
                    stroke-linecap="round"
                />

                <!-- Mobile line: 3.5M → 3.5M → jump to 10M → 12.5M steady -->
                <!-- y for 3.5M  = 188 - 3.5*9.33 = 155.3 ≈ 155 -->
                <!-- y for 10M   = 188 - 10*9.33  = 94.7  ≈ 95 -->
                <!-- y for 12.5M = 188 - 12.5*9.33= 71.4  ≈ 71 -->
                <polyline
                    points="50,155 149,155 248,155 297,95 346,88 446,71 545,71"
                    fill="none"
                    stroke="#00c9a7"
                    stroke-width="2.5"
                    stroke-linejoin="round"
                    stroke-linecap="round"
                />

                <!-- Annotation: sharp jump mid-2022 -->
                <line x1="272" y1="20" x2="272" y2="188" stroke="rgba(245,166,35,0.3)" stroke-width="1" stroke-dasharray="4,3"/>
                <text x="276" y="32" font-family="DM Mono, monospace" font-size="8.5" fill="rgba(245,166,35,0.8)">Mid-2022 jump</text>

                <!-- Data label endpoints -->
                <circle cx="545" cy="38" r="3.5" fill="#4facfe"/>
                <text x="549" y="41" font-family="DM Mono, monospace" font-size="8.5" fill="#4facfe">~16M</text>

                <circle cx="545" cy="71" r="3.5" fill="#00c9a7"/>
                <text x="549" y="74" font-family="DM Mono, monospace" font-size="8.5" fill="#00c9a7">~12.5M</text>
            </svg>

            <div class="chart-legend">
                <div class="legend-item">
                    <div class="legend-swatch" style="background:#4facfe;"></div>
                    Desktop URLs
                </div>
                <div class="legend-item">
                    <div class="legend-swatch" style="background:#00c9a7;"></div>
                    Mobile URLs
                </div>
            </div>
        </div>

        <div class="source-note">Source: HTTP Archive · httparchive.org/reports/state-of-the-web</div>
        <div class="slide-num">02 / 08</div>
    </section>

    <!-- ============================================================
         SLIDE 3 — PAGE WEIGHT TRENDS
         ============================================================ -->
    <section class="slide bg-grid content-slide" id="s3" aria-label="Page weight trends">

        <div class="slide-tag reveal d1">02 — Page Weight</div>
        <h2 class="slide-heading reveal d2">
            Median Page Weight Climbs Steadily to <em>~2,000 KB</em> on Desktop
        </h2>

        <div class="chart-wrap reveal d3">
            <svg viewBox="0 0 580 215" preserveAspectRatio="none" aria-label="Page weight time series with IQR bands">
                <!-- Grid lines -->
                <g stroke="rgba(79,172,254,0.08)" stroke-width="1">
                    <line x1="55" y1="15"  x2="545" y2="15"/>
                    <line x1="55" y1="53"  x2="545" y2="53"/>
                    <line x1="55" y1="91"  x2="545" y2="91"/>
                    <line x1="55" y1="129" x2="545" y2="129"/>
                    <line x1="55" y1="167" x2="545" y2="167"/>
                    <line x1="55" y1="192" x2="545" y2="192"/>
                </g>
                <!-- Y-axis labels (KB) -->
                <g font-family="DM Mono, monospace" font-size="8.5" fill="rgba(79,172,254,0.45)" text-anchor="end">
                    <text x="49" y="18">4,500</text>
                    <text x="49" y="56">3,500</text>
                    <text x="49" y="94">2,500</text>
                    <text x="49" y="132">1,500</text>
                    <text x="49" y="170">500</text>
                </g>
                <!-- X-axis labels -->
                <g font-family="DM Mono, monospace" font-size="9" fill="rgba(79,172,254,0.45)" text-anchor="middle">
                    <text x="55"  y="205">2020</text>
                    <text x="154" y="205">2021</text>
                    <text x="253" y="205">2022</text>
                    <text x="352" y="205">2023</text>
                    <text x="451" y="205">2024</text>
                    <text x="545" y="205">2025</text>
                </g>
                <line x1="55" y1="15" x2="55" y2="192" stroke="rgba(79,172,254,0.2)" stroke-width="1"/>

                <!--
                    Scale: Y-axis 0–5000KB over 177px (y=15 top = 5000KB, y=192 bottom = 0KB)
                    1 KB = 177/5000 = 0.0354 px/KB
                    y = 192 - (KB * 0.0354)

                    X: 5 years = 490px (x=55 to x=545), 98px/year

                    Desktop 75th percentile band: ~3000→4200 KB
                    Desktop 25th percentile band: ~700→900 KB
                    Desktop median: ~1600→2000 KB
                    Mobile median:  ~1500→1900 KB
                -->

                <!-- IQR shaded band (desktop): polygon of upper + reverse lower -->
                <!-- 75th pct: 3000→4200 KB -->
                <!-- 3000KB: y = 192 - 3000*0.0354 = 192 - 106.2 = 85.8 ≈ 86 -->
                <!-- 4200KB: y = 192 - 4200*0.0354 = 192 - 148.7 = 43.3 ≈ 43 -->
                <!-- 25th pct: 700→900 KB -->
                <!-- 700KB:  y = 192 - 700*0.0354  = 192 - 24.8 = 167.2 ≈ 167 -->
                <!-- 900KB:  y = 192 - 900*0.0354  = 192 - 31.9 = 160.1 ≈ 160 -->
                <polygon
                    points="55,86 154,80 253,74 352,65 451,56 545,43  545,160 451,163 352,165 253,166 154,167 55,167"
                    fill="rgba(79,172,254,0.06)"
                    stroke="none"
                />
                <!-- Upper bound line (75th pct) -->
                <polyline
                    points="55,86 154,80 253,74 352,65 451,56 545,43"
                    fill="none"
                    stroke="rgba(79,172,254,0.25)"
                    stroke-width="1"
                    stroke-dasharray="5,3"
                />
                <!-- Lower bound line (25th pct) -->
