                            e.preventDefault();
                            this.goTo(this.currentIdx + 1);
                            break;
                        case 'ArrowUp':
                        case 'ArrowLeft':
                            e.preventDefault();
                            this.goTo(this.currentIdx - 1);
                            break;
                        case 'PageDown':
                            e.preventDefault();
                            this.goTo(this.currentIdx + 1);
                            break;
                        case 'PageUp':
                            e.preventDefault();
                            this.goTo(this.currentIdx - 1);
                            break;
                        case 'Home':
                            e.preventDefault();
                            this.goTo(0);
                            break;
                        case 'End':
                            e.preventDefault();
                            this.goTo(this.total - 1);
                            break;
                    }
                });
            }

            /* --- Mouse wheel navigation (debounced) --- */
            setupWheelNav() {
                let wheelTimer = null;
                document.addEventListener('wheel', (e) => {
                    e.preventDefault();
                    if (wheelTimer) return;
                    wheelTimer = setTimeout(() => { wheelTimer = null; }, 800);
                    if (e.deltaY > 0) this.goTo(this.currentIdx + 1);
                    else              this.goTo(this.currentIdx - 1);
                }, { passive: false });
            }

            /* --- Touch/swipe navigation --- */
            setupTouchNav() {
                let touchStartY = null;
                document.addEventListener('touchstart', (e) => {
                    touchStartY = e.touches[0].clientY;
                }, { passive: true });

                document.addEventListener('touchend', (e) => {
                    if (touchStartY === null) return;
                    const delta = touchStartY - e.changedTouches[0].clientY;
